// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        // Fund the actor and deposit into C so the actor has a real balance.
        vm.deal(actor, type(uint256).max / 2);
        vm.prank(actor);
        c.deposit{value: type(uint256).max / 4}();

        // Admissible domain: amount within the actor's balance AND within
        // ether actually held by C, so `transfer` in the reference succeeds.
        amount = bound(amount, 1, address(c).balance);
        vm.assume(amount <= type(uint256).max / 4);

        uint256 before = address(c).balance;

        bool ok;
        vm.prank(actor);
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the withdraw succeeded, the contract must have paid out exactly
        // `amount` wei: its ether dropped by exactly `amount`.
        assertTrue(!ok || address(c).balance == before - amount);
    }
}
